values
  ('growth-12m-25pct-2y', 'Growth projection', 1, 'Revenue is €12M and grows 25% annually. What is revenue after 2 years?', 'Enter the ending revenue after compounding both years.', '€M', 18.75, 'Find 25% by dividing by four. Year 1 reaches €15M; repeat on the new total.'),
